import org.eclipse.rdf4j.sail.base.SnapshotSourceIsolationTest;
import org.eclipse.rdf4j.sail.base.SnapshotValidationSource;
import org.junit.jupiter.api.Test;

class MemorySnapshotSourceIsolationTest extends SnapshotSourceIsolationTest {

	@Test
	void waitingMemorySnapshotAndPublicationAcquisitionAreInterruptible() throws Exception {
		try (MemorySailStore backing = new MemorySailStore(false)) {
			SnapshotValidationSource source = (SnapshotValidationSource) backing.getExplicitSailSource();
			for (boolean snapshot : new boolean[] { true, false }) {
				CountDownLatch attempting = new CountDownLatch(1);
				CountDownLatch finished = new CountDownLatch(1);
				AtomicReference<Throwable> failure = new AtomicReference<>();
				AtomicBoolean interrupted = new AtomicBoolean();
				SailSink held = source.sink(IsolationLevels.READ_COMMITTED);
				held.prepare();
				Thread waiter = new Thread(() -> {
					attempting.countDown();
					try {
						if (snapshot) {
							try (var context = source.acquireSnapshot(IsolationLevels.SNAPSHOT)) {
								throw new AssertionError("An interrupted acquisition must not acquire a snapshot");
							}
						} else {
							try (SailSink sink = source.sink(IsolationLevels.READ_COMMITTED)) {
								sink.prepare();
								throw new AssertionError("An interrupted acquisition must not acquire publication");
							}
						}
					} catch (Throwable actual) {
						failure.set(actual);
						interrupted.set(Thread.currentThread().isInterrupted());
					} finally {
						finished.countDown();
					}
				}, "interrupted-memory-reservation");
				waiter.start();
				try {
					assertTrue(attempting.await(5, TimeUnit.SECONDS));
					waiter.interrupt();
					assertTrue(finished.await(5, TimeUnit.SECONDS),
							"Interruption must finish while the other publication remains reserved");
					SailException actual = assertInstanceOf(SailException.class, failure.get());
					assertInstanceOf(InterruptedException.class, actual.getCause());
					assertTrue(interrupted.get(), "Acquisition preserves the interrupt status");
				} finally {
					held.close();
					assertTrue(finished.await(5, TimeUnit.SECONDS));
					waiter.join();
				}
				try (var context = source.acquireSnapshot(IsolationLevels.SNAPSHOT)) {
					assertDoesNotThrow(() -> context.dataset().getNamespace("missing"));
				}
			}
		}
	}

	@Test
	void preparedMemoryReservationCanBeReleasedByConnectionCleanupOnAnotherThread() throws Exception {
		try (MemorySailStore backing = new MemorySailStore(false);
				ExecutorService executor = Executors.newFixedThreadPool(2)) {
			SailSource source = backing.getExplicitSailSource();
			SailSink prepared = executor.submit(() -> {
				SailSink sink = source.sink(IsolationLevels.NONE);
				sink.prepare();
				return sink;
			}).get(5, TimeUnit.SECONDS);
			assertDoesNotThrow(prepared::close,
					"MemoryStore's actual transaction reservation supports connection cleanup from another thread");
			executor.submit(() -> {
				try (SailSink sink = source.sink(IsolationLevels.READ_COMMITTED)) {
					sink.prepare();
					sink.flush();
				}
			}).get(5, TimeUnit.SECONDS);
		}
	}

	@Override
	protected SailStore createStore() {
		return new MemorySailStore(false);
	}
}
